mapper.select:
select BS.SUBJECT_NO as subjectNo, BS.SUBJECT_NAME as subjectName, BS.FSUBJECT_ID as fsubjectId, CASE WHEN BS.SUBJECT_TYPE ='01' THEN '资产类' WHEN BS.SUBJECT_TYPE ='02' THEN '负债类' WHEN BS.SUBJECT_TYPE ='03' THEN '资产负债共同类' WHEN BS.SUBJECT_TYPE ='04' THEN '所有者权益类' WHEN BS.SUBJECT_TYPE ='05' THEN '损益类' WHEN BS.SUBJECT_TYPE ='06' THEN '表外科目' WHEN BS.SUBJECT_TYPE ='07' THEN '登记簿类' END as subjectType, BS.SUBJECT_LEVEL as subjectLevel, BS.CREATE_USER as createUser, BS.CREATE_DEPT as createDept, BS.CREATE_TIME as createTime, BS.UPDATE_USER as updateUser, BS.UPDATE_TIME as updateTime, BS.UPDATE_TIME as updateDate, BS.DATA_SOURCE as dataSource, BS.STATUS as status, BS.REMARK as remark, BS.DESCRIBE as describe from BOK_SUBJECT BS
BS.SUBJECT_LEVEL = #{subjectLevel}
AND BS.FSUBJECT_ID = #{fsubjectId}
AND BS.SUBJECT_NO like #{subjectNo} || '%'
AND BS.SUBJECT_NAME like '%' || #{subjectName} || '%'
AND BS.SUBJECT_TYPE = #{subjectType}
AND BS.STATUS = #{status}
order by BS.BOOKSET_ID,BS.SUBJECT_NO,BS.SUBJECT_LEVEL

select SUBJECT_NO as id, SUBJECT_NAME as text FROM BOK_SUBJECT WHERE 1 = 1
AND BOOKSET_ID = #{booksetId}
AND SUBJECT_LEVEL = #{subjectLevel}
AND (SUBJECT_NO like '%' || #{search} || '%' OR SUBJECT_NAME like '%' || #{search} || '%')
GROUP BY SUBJECT_NO, SUBJECT_NAME

mapper.delete:
delete from BOK_SUBJECT
where BOOKSET_ID = #{booksetId,jdbcType=VARCHAR}
  and SUBJECT_NO like #{subjectNo,jdbcType=VARCHAR} || '%'

delete from BOK_SUBJECT_HAND_VALUE
where BOOKSET_ID = #{booksetId,jdbcType=VARCHAR}
  and SUBJECT_NO = #{subjectNo,jdbcType=VARCHAR}
